import { existsSync, readFileSync } from "fs";
import { resolve } from "path";
import { apiGuardParam, apiGuardParamExportName } from "../shared/wire/LambderApiOptionEntries.js";
import { headerLinesOf, loadApiOptionEntries, nameChangesOf, settleGeneratedFile, } from "./generatedTables.js";
/*
 * One guard's parameters as a generated module a browser may carry: one
 * export per API that declares the guard, holding the parameter it gives it,
 * and nothing else about any API.
 *
 * The file writeApiOptions writes holds every declaration, because a mock
 * and a test need every declaration. A screen that decides whether to offer
 * a control by the permission an endpoint's guard asks needs one guard's
 * parameter, for the endpoints it gates on. A table of them would still hand
 * every page that imports it the name of every API behind the guard and what
 * each asks, whichever of them its screens use. One export per API lets the
 * bundler keep exactly the ones the client imports, and keep no name at all:
 * the API's name sits in the export's type and doc comment, which a build
 * strips, and in its identifier, which a minifier renames.
 *
 * Each export is tagged with its API's name and the guard's
 * (LambderApiGuardParam), in types alone. A client function typed to the
 * tagged parameters takes only generated ones, so a hand-written literal,
 * which would restate the server's declaration and could drift from it, does
 * not compile.
 */
/** The tag type every export is asserted to, imported from the client entry, which is safe in a browser. */
const TAG_TYPE = "LambderApiGuardParam";
const defaultHeader = (guard) => [
    "Generated by writeApiGuardParams() from lambder/build. Do not edit.",
    "",
    `The parameter each API the server guards with "${guard}" gives that guard,`,
    "one export per API and nothing else about any API: a client imports the",
    "ones its screens gate on, and its bundle carries those alone.",
].join("\n");
/**
 * A plain-data value as the type `as const` gives it: its literals, readonly
 * all the way down. What each export is asserted to beside its tag, so the
 * tagged type keeps the literal the API declared.
 */
const constTypeOf = (value) => {
    if (Array.isArray(value))
        return `readonly [${value.map(constTypeOf).join(", ")}]`;
    if (value !== null && typeof value === "object") {
        const members = Object.entries(value).map(([key, member]) => `readonly ${JSON.stringify(key)}: ${constTypeOf(member)}`);
        return members.length ? `{ ${members.join("; ")} }` : "{}";
    }
    return JSON.stringify(value);
};
/**
 * One API's export as written, less the statement's semicolon: `export const
 * <name> = <JSON> as const as LambderApiGuardParam<"<api>", "<guard>", <type>>`.
 * A check renders each export it reads back again and compares the two, so
 * the identifier a client imports, the guard and the literal type are held
 * to what this writer would write, not only the value.
 */
const exportLineOf = (name, param, guard) => `export const ${apiGuardParamExportName(name)} = ${JSON.stringify(param)} as const as ${TAG_TYPE}<${JSON.stringify(name)}, ${JSON.stringify(guard)}, ${constTypeOf(param)}>`;
/** The start of one export, far enough to read back its parameter's JSON and its API's name. */
const EXPORT_LINE = new RegExp(`^export const [A-Za-z_$][\\w$]* = (.+) as const as ${TAG_TYPE}<("(?:[^"\\\\]|\\\\.)*"), `);
/** The tag's import, in whatever spacing and quotes a formatter gives it, since no `// prettier-ignore` sits above it. */
const IMPORT_LINE = new RegExp(`^import type \\{\\s*${TAG_TYPE}\\s*\\} from (["'])lambder/client\\1;?$`);
/** The empty module of a guard no API declares, however a formatter spaces it. */
const EMPTY_EXPORT_LINE = /^export \{\s*\};?$/;
/**
 * The parameters a file already holds, by API name, or null for a file that
 * does not hold them as written. As written means the tag's import and one
 * export per API, each the line exportLineOf renders for its API and value,
 * or the empty module alone for a guard no API declares. Anything else makes
 * it null: another statement, an export renamed by hand or written for
 * another guard, an API exported twice, a missing import, a file with no
 * statement at all. Comments, blank lines, re-indentation, line endings and
 * the semicolons change nothing.
 */
const readGuardParams = (contents, guard) => {
    const params = {};
    let imported = false;
    let empty = false;
    for (const line of contents.split(/\r?\n/).map((text) => text.trim())) {
        if (line === "" || line.startsWith("//") || line.startsWith("/*") || line.startsWith("*"))
            continue;
        if (IMPORT_LINE.test(line)) {
            imported = true;
            continue;
        }
        if (EMPTY_EXPORT_LINE.test(line)) {
            empty = true;
            continue;
        }
        const match = EXPORT_LINE.exec(line);
        if (!match)
            return null;
        try {
            const param = JSON.parse(match[1]);
            const name = JSON.parse(match[2]);
            if (typeof name !== "string" || Object.prototype.hasOwnProperty.call(params, name))
                return null;
            if (line.replace(/;$/, "") !== exportLineOf(name, param, guard))
                return null;
            params[name] = param;
        }
        catch {
            return null;
        }
    }
    const held = Object.keys(params).length > 0 ? imported && !empty : empty && !imported;
    return held ? params : null;
};
/** The file's statements after its header: the tag's import and one export per API, or an empty export for a guard no API declares. */
const statementLinesOf = (params, guard, semicolon) => {
    const names = Object.keys(params);
    if (names.length === 0)
        return [`export {}${semicolon}`];
    return [
        `import type { ${TAG_TYPE} } from "lambder/client"${semicolon}`,
        ...names.flatMap((name) => [
            "",
            `/** What ${name} gives the "${guard}" guard. */`,
            // Keeps a formatter off the JSON a check reads back.
            "// prettier-ignore",
            `${exportLineOf(name, params[name], guard)}${semicolon}`,
        ]),
    ];
};
/**
 * Writes one guard's parameters as a module of one export per API, or checks
 * the one on disk, and says which APIs moved.
 *
 * ```ts
 * import { writeApiGuardParams } from "lambder/build";
 *
 * const result = await writeApiGuardParams({
 *     module: "server/src/index.ts",
 *     exportName: "lambder",
 *     guard: "store",
 *     file: "web/src/generated/storeGuardParams.generated.ts",
 *     check: process.argv.includes("--check"),
 * });
 * ```
 *
 * API `orders.list` exports `ordersListGuardParam`: the literal it declared,
 * `true` for a guard named without a parameter (the string and list forms),
 * typed LambderApiGuardParam<"orders.list", "store", literal>. Two APIs whose
 * names export under one identifier fail the write, and so does a parameter
 * that is not plain data, as it does for writeApiOptions, or that is null,
 * which no tag can carry.
 */
export const writeApiGuardParams = async (options) => {
    const file = resolve(options.file);
    const entries = await loadApiOptionEntries(options, "writeApiGuardParams");
    if (!Object.prototype.hasOwnProperty.call(entries.guards, options.guard)) {
        const declared = Object.keys(entries.guards);
        throw new Error(`writeApiGuardParams: the server declares no guard "${options.guard}" (it declares ${declared.length ? declared.map((name) => `"${name}"`).join(", ") : "none"}).`);
    }
    const params = {};
    const exportedBy = new Map();
    for (const name of Object.keys(entries.apis).sort()) {
        const param = apiGuardParam(entries.apis, name, options.guard);
        if (param === undefined)
            continue;
        if (param === null) {
            throw new Error(`writeApiGuardParams: "${name}" gives the "${options.guard}" guard null, which an export cannot carry with its tag; give the guard another value.`);
        }
        const exportName = apiGuardParamExportName(name);
        const taken = exportedBy.get(exportName);
        if (taken !== undefined) {
            throw new Error(`writeApiGuardParams: "${taken}" and "${name}" would both export ${exportName}; rename one of them.`);
        }
        exportedBy.set(exportName, name);
        params[name] = param;
    }
    const previousText = existsSync(file) ? readFileSync(file, "utf8") : null;
    const previous = previousText === null ? null : readGuardParams(previousText, options.guard);
    const changes = nameChangesOf(params, previous ?? {});
    const count = Object.keys(params).length;
    const semicolon = options.semicolons === false ? "" : ";";
    const settled = settleGeneratedFile({
        name: options.file, file, check: options.check, previousText, readBack: previous !== null,
        tables: [{ name: `${options.guard} params`, count, changes }],
        held: `${count} APIs guarded by "${options.guard}"`,
        tablesNoun: "the parameters",
        unmovedLine: "no parameters changed",
        render: () => [
            ...headerLinesOf(options.header ?? defaultHeader(options.guard)),
            "",
            ...statementLinesOf(params, options.guard, semicolon),
            "",
        ].join("\n"),
    });
    return { ...settled, file, count, changes };
};
